mapper.select:
SELECT site, profile, property_key, se, property_name, property_value
FROM zt_property_source

    AND site    = #{site}
    AND profile = #{profile}
    AND se      = #{se}

ORDER BY property_key

mapper.update:
UPDATE zt_property_source
SET se             = #{se},
    property_name  = #{propertyName},
    property_value = #{propertyValue}
WHERE site         = #{site}
  AND profile      = #{profile}
  AND property_key = #{propertyKey}

mapper.delete:
DELETE FROM zt_property_source
WHERE site         = #{site}
  AND profile      = #{profile}
  AND property_key = #{propertyKey}
